const COLOR_MAP = {
  blue: "#3a3ade",
  green: "#64b13d",
  yellow: "#eed200",
  red: "#d42626",
  gray: "#7f7f7f",
  black: "#000000",
  orange: "#e87e0a",
  purple: "#7f24a8",
  brown: "#97613f",
  cyan: "#4fced1",
  neutral: "#c7c7c7",
};

const MONTH_NAMES = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"
];

function parsePOIText(text) {
  const now = new Date();
  const twoWeeksAgo = new Date(now.getTime() - 14 * 24 * 60 * 60 * 1000);

  return text.trim().split("\n").map((line) => {
    const parts = line.match(/(?:[^,"]+|"[^"]*")+/g)?.map(p => p.trim().replace(/^"|"$/g, ''));
    if (!parts || parts.length < 8) return null;

    const [x, y, year, month, day, colorKey, iconName, label] = parts;
    const date = new Date(+year, +month - 1, +day);

    if (date < twoWeeksAgo || !(colorKey in COLOR_MAP)) return null;

    const monthName = MONTH_NAMES[+month - 1];
    const tooltip = `<b>${monthName} ${day}:</b> ${label}`;

    return {
      x: +x,
      y: +y,
      color: COLOR_MAP[colorKey],
      iconPath: `${import.meta.env.BASE_URL}assets/icons/${iconName}.png`,
      label: tooltip,
    };
  }).filter(Boolean);
}

function addPOIMarker(map, { x, y, color, iconPath, label }) {
  const latLng = map.unproject([x, y], 0);

  const icon = L.divIcon({
    className: "custom-poi-icon",
    html: `
      <div class="poi-wrapper" style="
        width: 28px;
        height: 28px;
        border-radius: 50%;
        background-color: ${color};
        display: flex;
        justify-content: center;
        align-items: center;
        box-shadow: 1px 1px 1px #00000088;
      ">
        <img src="${iconPath}" style="width: 24px; height: 24px;" />
      </div>
    `,
    iconSize: [32, 32],
    iconAnchor: [16, 16],
    tooltipAnchor: [0, -20],
  });

  const marker = L.marker(latLng, { icon }).addTo(map);
  if (label) {
    marker.bindTooltip(label, { permanent: false, direction: "top", className: "custom-poi-tooltip"});
  }
}

function addPolygon(map, inputPolygons, color, tooltipText) {
  const toLatLng = (pt) => {
    let x, y;
    if (Array.isArray(pt)) {
      [x, y] = pt;
    } else if (typeof pt === "object" && pt !== null && "x" in pt && "y" in pt) {
      ({ x, y } = pt);
    } else {
      throw new Error(`Invalid coordinate point: ${JSON.stringify(pt)}`);
    }

    if (typeof x !== "number" || typeof y !== "number") {
      throw new Error(`Invalid coordinate values: ${JSON.stringify(pt)}`);
    }

    return map.unproject([x, y], 0);
  };

  const normalizePolygon = (poly) => {
    // poly can be:
    // - a ring (simple polygon): [ {x,y}, ... ]
    // - or a polygon with holes: [ [ {x,y}, ... ], [ {x,y}, ... ] ]
    if (!Array.isArray(poly)) {
      throw new Error("Polygon must be an array");
    }

    if (poly.length === 0) return [];

    if (typeof poly[0]?.x === "number") {
      // Simple polygon
      return [poly.map(toLatLng)];
    }

    // Polygon with holes
    return poly.map(ring => ring.map(toLatLng));
  };

  const latLngMultiPoly = inputPolygons.map(normalizePolygon);

  const polygon = L.polygon(latLngMultiPoly, {
    color,
    weight: 1,
    fillOpacity: 0.3,
  }).addTo(map);

  if (tooltipText) {
     polygon.bindTooltip(tooltipText, { permanent: false, direction: "top", className: "custom-poi-tooltip"});
  }

  polygon.on("mouseover", () => {
    polygon.setStyle({ weight: 2 });
  });
  polygon.on("mouseout", () => {
    polygon.setStyle({ weight: 1 });
  });

  polygon.on("click", (e) => {
    e.originalEvent.preventDefault();
  });

  return polygon;
}

